mapper.update:
update system_notice
title = #{title}, content = #{content},
where id = #{id}

mapper.select:
select id, title, content, publisher_id as publisherId, publish_time as publishTime, type
from system_notice
where id = #{id}

select id, title, content, publisher_id as publisherId, publish_time as publishTime, type
from system_notice

    publisher_id = #{publisherId}

        and title like concat('%', #{title}, '%')


        and publish_time >= #{beginTime}


        and publish_time <= #{endTime}


order by id desc

select n.id, n.title, n.content, n.publisher_id as publisherId, n.publisher_id as userId, u.real_name as publisherRealName, n.publish_time as publishTime, n.type from system_notice n left join user u on n.publisher_id = u.id
and u.real_name like concat('%', #{publisherRealName}, '%')
and n.publish_time >= #{beginTime}
and n.publish_time <= #{endTime}
order by n.publish_time desc, n.id desc

select n.id, n.title, n.content, n.publisher_id as publisherId, n.publisher_id as userId, u.real_name as publisherRealName,
n.publish_time as publishTime, n.type
from system_notice n
left join user u on n.publisher_id = u.id

    n.type = #{type}

        and n.publisher_id = #{publisherId}


order by n.publish_time desc, n.id desc
limit #{limit}
